function normalizeStyle(styleAttr: string): string {
  const props = new Map<string, string>();
  for (const decl of styleAttr.split(";")) {
    const idx = decl.indexOf(":");
    if (idx < 0) {
      continue;
    }
    const prop = decl.slice(0, idx).trim().toLowerCase();
