    block("WIDTH_", &[
        ("FILL", "-1".into()),
        ("HUG", "-2".into()),
    ]);

    for (prefix, items) in enum_codes() {
        let comment = match prefix {
            "ALIGN_" => "Alignment enum (protocol ENUM values)",
            "SHAPE_" => "SHAPE_KIND",
            "TEXT_ALIGN_" | "TRUNCATION_" | "CONTENT_MODE_" | "FONT_STYLE_" | "FONT_DESIGN_"
